import sys

def main():
    num, s = map(int, sys.stdin.read().split())
    seen = {num}
    frontier = [num]
    for _ in range(s):
        nxt = []
        for v in frontier:
            if v % 2 == 0 and v // 2 not in seen:
                seen.add(v // 2)
                nxt.append(v // 2)
            if v > 0 and v - 1 not in seen:
                seen.add(v - 1)
                nxt.append(v - 1)
        frontier = nxt
        if not frontier:
            break
    print(len(seen))

